INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('cc90124b-85b7-4ab1-8345-194087be6fcc','241965d7-280c-4dfa-b258-97b3c9b915be','08717303-45fb-4161-8b84-c2540337cdcb','cat-ingredient-prod','黑鱼',replace('## 基本信息\n- **产地**：中国南方江河、湖泊水域（资料未提供详细产地，仅作为鱼肉来源提及）\n- **最佳季节**：全年均可，夏季肉质相对更肥美（资料未提供，按常识补充）\n\n## 营养价值\n- 高蛋白、低脂肪，富含不饱和脂肪酸，肉质紧实嫩滑，适合做水煮鱼等需要片成薄片的菜式。\n\n## 选购与储存\n- 选购活鱼时看眼睛清澈、鳞片完整、体表无破损；买片好的鱼片则看鱼肉颜色鲜亮、无异味。\n- 冷冻鱼片密封冷藏可保存1-2个月，吃前解冻。\n\n## 烹饪建议\n- 适合做水煮鱼、酸菜鱼等需要鱼片的菜式，切片后嫩滑不易碎。\n- 参考菜谱 [[少油简化版水煮鱼]]。\n\n## 关联页面\n- [[草鱼]]\n','\n',char(10)),'[0.020599365234375,0.00855255126953125,-0.052093505859375,0.0330810546875,0.01187896728515625,-0.05474853515625,0.028594970703125,0.044891357421875,0.00829315185546875,0.02459716796875,-0.004352569580078125,0.00919342041015625,-0.01953125,0.0162200927734375,-0.0184783935546875,0.0070648193359375,-0.0251617431640625,0.01306915283203125,0.00936126708984375,-0.008331298828125,-0.00415802001953125,0.00577545166015625,-0.024383544921875,-0.013824462890625,0.01519775390625,-0.0170135498046875,-0.004131317138671875,0.00823974609375,0.026519775390625,0.01861572265625,-0.0005445480346679688,0.0177764892578125,-0.0276336669921875,0.00775146484375,0.018890380859375,-0.034759521484375,-0.0207672119140625,-0.032562255859375,-0.0233154296875,-0.0065460205078125,0.0120849609375,-0.0098114013671875,0.018768310546875,-0.0118408203125,0.025238037109375,-0.046875,0.0067596435546875,-0.0164031982421875,-0.04986572265625,-0.0301513671875,0.059326171875,-0.01152801513671875,0.029937744140625,-0.027984619140625,0.0277099609375,0.03997802734375,0.0645751953125,-0.027740478515625,0.02191162109375,0.041595458984375,0.003665924072265625,0.01305389404296875,0.010467529296875,-0.0099945068359375,0.006786346435546875,0.02276611328125,0.0285186767578125,0.0193939208984375,-0.04705810546875,0.00620269775390625,-0.0062255859375,0.046661376953125,0.0198516845703125