INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('f9133c06-e7f6-4d4e-85e2-3bb98b72809e','241965d7-280c-4dfa-b258-97b3c9b915be','08717303-45fb-4161-8b84-c2540337cdcb','cat-ingredient-prod','草鱼',replace('## 基本信息\n- **产地**：中国各地淡水湖泊、河流均有养殖（资料未提供详细产地，仅作为鱼肉来源提及）\n- **最佳季节**：全年均可（资料未提供，按常识补充）\n\n## 营养价值\n- 蛋白质丰富，脂肪含量低，肉质细嫩，适合切片做水煮鱼等菜式。\n\n## 选购与储存\n- 活鱼选眼睛清澈、鳃色鲜红、体表无伤的；冷冻鱼片需密封冷藏保存。\n\n## 烹饪建议\n- 与 [[黑鱼]] 一样适合片成鱼片做水煮鱼、酸菜鱼等。\n- 参考菜谱 [[少油简化版水煮鱼]]。','\n',char(10)),'[0.016693115234375,0.0182342529296875,-0.041656494140625,0.0316162109375,0.0170440673828125,-0.07183837890625,0.0223846435546875,0.048980712890625,0.0004572868347167969,0.01508331298828125,-0.01261138916015625,-0.013916015625,-0.00921630859375,0.00223541259765625,-0.01459503173828125,0.00949859619140625,-0.0272369384765625,0.0196380615234375,0.00980377197265625,-0.0144195556640625,-0.0174102783203125,0.00412750244140625,-0.0098724365234375,-0.0128173828125,0.017822265625,-0.031219482421875,-0.0019741058349609375,0.0086822509765625,0.01355743408203125,0.020355224609375,-0.022705078125,0.0030803680419921875,-0.0214385986328125,0.01505279541015625,0.01522064208984375,-0.037017822265625,-0.03143310546875,-0.03094482421875,-0.0203399658203125,0.0027713775634765625,0.0255889892578125,-0.0287628173828125,0.0167999267578125,-0.00450897216796875,0.0264129638671875,-0.04998779296875,-0.0137176513671875,-0.01763916015625,-0.043975830078125,-0.03472900390625,0.0328369140625,0.0032215118408203125,0.02685546875,-0.037567138671875,0.0400390625,0.052276611328125,0.05072021484375,-0.00873565673828125,0.031524658203125,0.068603515625,0.00148773193359375,0.006076812744140625,0.0266571044921875,-0.006229400634765625,0.0024852752685546875,0.0199432373046875,0.0401611328125,0.026153564453125,-0.03973388671875,0.01483154296875,-0.019439697265625,0.0496826171875,0.0300445556640625,-0.0045623779296875,0.00952911376953125,-0.01053619