INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('d7f133e9-8080-47c5-b17c-716fd512321a','241965d7-280c-4dfa-b258-97b3c9b915be','08717303-45fb-4161-8b84-c2540337cdcb','e972b501-bb68-49bd-82e6-afb744d40de3','鱼片上浆技巧',replace('## 主题概述\n上浆是让鱼片口感嫩滑、不易煮散的核心步骤。关键在于：鱼片洗净沥干后，依次加入盐、白胡椒、料酒、蛋清、玉米淀粉抓匀，最后封一层食用油，静置10分钟，再下锅。\n\n## 关联人物\n（暂无）\n\n## 关联事件\n- 应用于 [[少油简化版水煮鱼]] 的鱼片预处理阶段\n\n## 资料来源\n- 资料1：少油简化版水煮鱼（用户提供）\n\n## 我的观点\n- 鱼片一定先沥干水分再上浆，否则浆液挂不住，口感容易发柴。\n- 蛋清+淀粉的组合能锁住水分，使鱼片嫩滑。\n- 最后封油可以防止鱼片下锅粘连，也便于静置时隔绝氧化。','\n',char(10)),'[0.0190582275390625,0.00897979736328125,-0.0242767333984375,0.004425048828125,0.0015954971313476562,-0.046295166015625,0.048553466796875,0.019927978515625,-0.0242156982421875,0.00461578369140625,-0.0008740425109863281,-0.0200958251953125,0.028472900390625,-0.007843017578125,0.0088958740234375,0.029327392578125,0.02069091796875,0.0204620361328125,0.03192138671875,-0.00991058349609375,-0.0017547607421875,0.01146697998046875,-0.03265380859375,-0.01103973388671875,0.0009660720825195312,-0.0093994140625,-0.0112152099609375,0.0176239013671875,0.0271453857421875,-0.02569580078125,0.006069183349609375,-0.0272216796875,-0.045806884765625,-0.022430419921875,0.016143798828125,-0.03399658203125,0.0261688232421875,-0.05572509765625,-0.01290130615234375,0.042327880859375,0.01983642578125,-0.0130767822265625,-0.01446533203125,0.01378631591796875,-0.01348114013671875,-0.01373291015625,-0.0135650634765625,-0.01456451416015625,0.001392364501953125,0.0014429092407226562,0.0261688232421875,-0.0299530029296875,0.030242919921875,-0.05517578125,0.0187530517578125,0.060577392578125,0.042694091796875,-0.005588531494140625,-0.021881103515625,0.02960205078125,-0.0268707275390625,0.0284423828125,0.0112762451171875,-0.01325225830078125,0.0175933837890625,0.044403076171875,-0.007312774658203125,0.0207061767578125,-0.04510498046875,-0.0347900390625,-0.01332855224609375,0.03564453125,0