INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('88914af8-0041-4cfa-be3c-e6613c347785','241965d7-280c-4dfa-b258-97b3c9b915be','08717303-45fb-4161-8b84-c2540337cdcb','e972b501-bb68-49bd-82e6-afb744d40de3','鱼片煮制火候',replace('## 主题概述\n煮鱼片时转中小火分散下锅，轻推散不要大力搅拌，鱼片变白、微微卷起（约1分钟）立即关火，避免大火把鱼片煮碎煮老。\n\n## 关联人物\n（暂无）\n\n## 关联事件\n- 应用于 [[少油简化版水煮鱼]] 的煮鱼片阶段\n\n## 资料来源\n- 资料1：少油简化版水煮鱼（用户提供）\n\n## 我的观点\n- 中小火下锅后自然静置1分钟左右即可，不要持续搅拌。\n- 鱼片变白卷曲是最直观的判断标准，比计时更可靠。\n- 关火后连汤倒入碗中，利用余温让鱼片继续熟化，避免煮老。','\n',char(10)),'[0.0195465087890625,-0.01029205322265625,-0.0538330078125,0.025177001953125,-0.01507568359375,-0.044891357421875,0.031951904296875,0.055084228515625,0.004486083984375,0.0018377304077148438,0.002918243408203125,-0.021514892578125,0.0318603515625,0.01021575927734375,0.008453369140625,-0.0017948150634765625,0.0137176513671875,0.0177459716796875,0.0292816162109375,0.001552581787109375,0.0156402587890625,0.0297393798828125,-0.0247039794921875,-0.001514434814453125,0.023895263671875,-0.01409912109375,-0.0017156600952148438,-0.005458831787109375,0.0648193359375,0.0227813720703125,-0.023223876953125,-0.0294189453125,-0.03411865234375,-0.0089569091796875,0.0005645751953125,0.01007080078125,-0.0242156982421875,-0.04364013671875,-0.0231475830078125,0.047607421875,0.05303955078125,-0.054473876953125,0.0021686553955078125,0.0129547119140625,0.0220794677734375,-0.02423095703125,-0.034698486328125,-0.028228759765625,-0.01285552978515625,-0.0218505859375,0.056915283203125,-0.0179595947265625,0.0198822021484375,-0.0423583984375,0.030853271484375,0.051483154296875,0.048919677734375,-0.0147705078125,-0.0284423828125,0.051422119140625,0.016082763671875,0.00534820556640625,-0.01555633544921875,-0.051361083984375,-0.034698486328125,0.0198516845703125,0.035858154296875,0.022186279296875,-0.0205078125,0.00830841064453125,-0.0292510986328125,0.03399658203125,0.01727294921875,-0.0257110595703125,0.0122