INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('bcfe9f8b-eac1-4c47-becd-d0f3f6a25e94','241965d7-280c-4dfa-b258-97b3c9b915be','08717303-45fb-4161-8b84-c2540337cdcb','e972b501-bb68-49bd-82e6-afb744d40de3','豆瓣酱炒红油火候',replace('## 主题概述\n锅中放少量油（2勺），小火下姜蒜葱段爆香后放入 [[郫县豆瓣酱]]，持续小火慢慢炒出红油，火大容易糊锅变苦。\n\n## 关联人物\n（暂无）\n\n## 关联事件\n- 应用于 [[少油简化版水煮鱼]] 的熬汤底阶段\n\n## 资料来源\n- 资料1：少油简化版水煮鱼（用户提供）\n\n## 我的观点\n- 全程保持小火是炒出红油而不糊的核心。\n- 红油炒出来后汤底颜色更红润、味道更浓郁，是这道菜的灵魂步骤。','\n',char(10)),'[-0.055450439453125,0.000873565673828125,-0.038482666015625,0.023590087890625,0.0208282470703125,-0.0235137939453125,0.041473388671875,0.051025390625,-0.026123046875,-0.020782470703125,0.0021190643310546875,-0.0211181640625,0.03662109375,0.0182342529296875,0.004058837890625,0.017059326171875,0.0091552734375,0.0205535888671875,0.030120849609375,0.0106048583984375,0.018280029296875,0.061859130859375,-0.03338623046875,-0.011322021484375,0.01010894775390625,0.007568359375,-0.001659393310546875,-0.008514404296875,0.048919677734375,-0.0005159378051757812,-0.0308990478515625,-0.01470184326171875,-0.064453125,-0.01171875,-0.010345458984375,0.02545166015625,-0.0579833984375,-0.036407470703125,-0.00685882568359375,0.030487060546875,0.06072998046875,-0.053985595703125,-0.0215606689453125,-0.0005726814270019531,0.002277374267578125,-0.03753662109375,-0.0229034423828125,-0.03118896484375,-0.0212860107421875,-0.0178680419921875,0.00849151611328125,-0.0435791015625,0.036773681640625,-0.01082611083984375,0.032073974609375,0.045989990234375,0.020660400390625,0.07135009765625,-0.037322998046875,0.05108642578125,-0.03900146484375,0.00039315223693847656,0.041351318359375,-0.03802490234375,-0.025360107421875,0.01163482666015625,0.007205963134765625,0.01506805419921875,-0.0233917236328125,0.00022840499877929688,-0.0166778564453125,0.0267181396484375,0.008544921875,-0.0257720947265625,-0.0222930908203125,-0.000537872314453125,0.