INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('d5c80b75-73c8-4b66-90db-084c6ea8bf65','241965d7-280c-4dfa-b258-97b3c9b915be','08717303-45fb-4161-8b84-c2540337cdcb','e972b501-bb68-49bd-82e6-afb744d40de3','少油激香淋油法',replace('## 主题概述\n传统水煮鱼结尾需大量热油泼辣椒花椒，油烟大。简化版改为：碗面撒干辣椒、花椒、蒜末，锅中仅烧1勺油至微微冒烟，淋上去即可，油烟大幅减少。\n\n## 关联人物\n（暂无）\n\n## 关联事件\n- 应用于 [[少油简化版水煮鱼]] 的最后激香步骤\n\n## 资料来源\n- 资料1：少油简化版水煮鱼（用户提供）\n\n## 我的观点\n- 油量减少后激香效果略弱，可根据喜好适量增加辣椒和花椒数量来补偿风味。\n- 油温微微冒烟即可，过高会糊化蒜末影响味道。','\n',char(10)),'[-0.05853271484375,0.0022983551025390625,-0.0423583984375,-0.01629638671875,-0.004222869873046875,-0.055816650390625,0.066650390625,0.0673828125,-0.0137786865234375,-0.01309967041015625,-0.013641357421875,-0.02227783203125,0.0023040771484375,0.0055694580078125,-0.00844573974609375,0.0052490234375,0.00983428955078125,0.0268096923828125,0.033843994140625,0.00814056396484375,-0.029266357421875,0.041717529296875,-0.0153656005859375,0.03759765625,-0.006420135498046875,-0.0195465087890625,-0.0200653076171875,-0.0008301734924316406,0.01190185546875,-0.01039886474609375,0.011627197265625,0.033203125,-0.06109619140625,0.0033893585205078125,-0.0255889892578125,0.00429534912109375,-0.01247406005859375,-0.04705810546875,0.006450653076171875,0.0226898193359375,0.059417724609375,-0.038299560546875,0.0216522216796875,-0.007099151611328125,-0.00270843505859375,-0.0015802383422851562,-0.01220703125,-0.027130126953125,-0.035919189453125,-0.0206298828125,0.0457763671875,-0.0103607177734375,0.01317596435546875,-0.02716064453125,0.02984619140625,0.054962158203125,0.027679443359375,0.05877685546875,-0.040069580078125,0.032135009765625,-0.0287628173828125,-0.0001322031021118164,-0.004138946533203125,-0.059478759765625,0.0289154052734375,0.03265380859375,0.0063323974609375,0.00980377197265625,0.00177764892578125,0.046966552734375,-0.0014324188232421875,0.02557373046875,0.0248260498046875,-0.0322265625,-0.02069