INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('366cc6b5-a3a0-434d-b285-14227c18ac97','5d029248-9072-4943-a987-8f0a136362dc','ada7ec6a-9020-4277-9469-fc0d5d4208a0','435429cb-a9cc-4b5c-b045-5875c8a278b6','鱼片腌制上浆技巧',replace('## 主题概述\n鱼片在煮之前先腌制上浆，能让鱼肉更嫩滑、不易煮碎。做法是：鱼片洗净沥干水分，加入[[盐]]一小撮、[[白胡椒粉]]少许、[[料酒]]1勺、蛋清半个、玉米淀粉1.5勺抓匀，最后封几滴[[食用油]]，静置10分钟。\n\n## 关联人物\n无\n\n## 关联事件\n无\n\n## 资料来源\n少油简化版水煮鱼资料\n\n## 我的观点\n封油这一步很关键，能锁住水分，下锅时鱼片也不容易粘连。\n\n关联菜谱：[[少油水煮鱼]]','\n',char(10)),'[0.0107879638671875,0.0013675689697265625,-0.0307769775390625,0.0221710205078125,0.0025310516357421875,-0.057464599609375,0.05029296875,0.035614013671875,-0.025848388671875,-0.00026726722717285156,-0.007266998291015625,-0.019073486328125,0.01352691650390625,-0.0060577392578125,-0.0010271072387695312,0.0240936279296875,0.02001953125,0.019866943359375,0.037139892578125,-0.01074981689453125,-0.01041412353515625,0.011566162109375,-0.0277862548828125,-0.01097869873046875,-0.0032787322998046875,-0.0156402587890625,-0.0228118896484375,0.0157623291015625,0.040496826171875,-0.027587890625,0.00489044189453125,-0.0309600830078125,-0.0287017822265625,-0.002483367919921875,0.033599853515625,-0.027130126953125,0.0267486572265625,-0.06536865234375,-0.0030269622802734375,0.04296875,0.0257110595703125,-0.019073486328125,-0.01515960693359375,0.00009739398956298828,-0.0103912353515625,-0.007297515869140625,-0.0202178955078125,-0.005825042724609375,0.00421905517578125,0.007747650146484375,0.037567138671875,-0.032867431640625,0.029541015625,-0.05828857421875,0.040283203125,0.052154541015625,0.053619384765625,0.01499176025390625,-0.000028908252716064453,0.03424072265625,-0.0273284912109375,0.01398468017578125,0.00434112548828125,-0.01422882080078125,0.0172882080078125,0.037689208984375,-0.0082244873046875,0.030364990234375,-0.042236328125,-0.0328369140625,-0.000055849552154541016,0.0509033203125,0.05596923828125,-0.0347595