INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('4a526c92-949e-4b02-8bcc-17f27766330a','5d029248-9072-4943-a987-8f0a136362dc','ada7ec6a-9020-4277-9469-fc0d5d4208a0','435429cb-a9cc-4b5c-b045-5875c8a278b6','水煮鱼少油做法技巧',replace('## 主题概述\n传统水煮鱼要泼一大锅热油，油烟大、用油多。少油版的做法是：熬汤底时只用2勺油炒豆瓣酱出红油，最后激香时锅里只烧1勺油，微微冒烟淋在干辣椒、花椒、蒜末上即可。全程总共只用3勺油。\n\n## 关联人物\n无\n\n## 关联事件\n无\n\n## 资料来源\n少油简化版水煮鱼资料\n\n## 我的观点\n少油版油烟小很多，家里做更清爽，味道也不差。注意豆瓣酱本身有盐，[[生抽]]别放多，防止过咸。\n\n关联菜谱：[[少油水煮鱼]]','\n',char(10)),'[-0.05548095703125,-0.0021877288818359375,-0.053192138671875,0.021148681640625,0.0241241455078125,-0.06829833984375,0.045013427734375,0.05145263671875,-0.0088043212890625,0.0027637481689453125,-0.01708984375,-0.02459716796875,0.021697998046875,-0.0118560791015625,-0.016143798828125,0.0237274169921875,-0.01019287109375,0.0396728515625,0.024993896484375,-0.01126861572265625,-0.0288543701171875,0.040252685546875,-0.01605224609375,0.00432586669921875,-0.0003643035888671875,-0.027130126953125,-0.00203704833984375,-0.003986358642578125,0.0252532958984375,-0.024322509765625,0.00499725341796875,-0.0010461807250976562,-0.062347412109375,0.009918212890625,-0.01026153564453125,0.01519012451171875,-0.026947021484375,-0.054779052734375,-0.005859375,0.0250701904296875,0.0657958984375,-0.048095703125,-0.00055694580078125,-0.0035800933837890625,0.00986480712890625,-0.0004260540008544922,-0.0302734375,-0.01702880859375,-0.00753021240234375,-0.0190277099609375,0.047821044921875,-0.0174102783203125,0.0245819091796875,-0.05181884765625,0.039337158203125,0.06036376953125,0.041961669921875,0.061676025390625,-0.0242156982421875,0.046630859375,-0.051849365234375,-0.0098876953125,0.01058197021484375,-0.03289794921875,0.017974853515625,0.0286102294921875,-0.0013093948364257812,0.0117034912109375,-0.0243377685546875,0.043121337890625,-0.01580810546875,0.0316162109375,0.04534912109375,-0.023406982421875,-0.01088714599609375,