INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('36974130-b2a9-4bb7-bc4d-9f69cc5605b6','c094822a-2476-4aaa-b13f-5026ba0281e7','ada7ec6a-9020-4277-9469-fc0d5d4208a0','ef4aed26-1124-4625-ac16-fb2b674a2514','栊翠庵',replace('## 位置\n[[大观园]]内，[[妙玉]]的修行处。\n\n## 去过的经历\n- [[刘姥姥进大观园]]时，一行人来到栊翠庵。[[妙玉]]清高，拿出好茶招待众人：给[[贾母]]用旧年雨水泡的老君眉，单独给[[贾宝玉]]、[[薛宝钗]]、[[林黛玉]]用珍藏的梅花雪水。\n- [[妙玉]]拿一个粗茶杯给[[刘姥姥]]，刘姥姥喝完，妙玉嫌杯子被她用过，打算直接扔掉，[[贾宝玉]]劝她，把杯子送给刘姥姥。\n\n## 整体印象\n清雅脱俗，与[[妙玉]]清高的性格相合。\n\n## 关联人物\n[[妙玉]]、[[刘姥姥]]、[[贾母]]、[[贾宝玉]]、[[薛宝钗]]、[[林黛玉]]','\n',char(10)),'[-0.0357666015625,0.0192413330078125,-0.0675048828125,-0.0264739990234375,-0.01543426513671875,-0.0290069580078125,-0.0197296142578125,-0.0297698974609375,0.0028076171875,-0.0197906494140625,0.01468658447265625,-0.00443267822265625,-0.005748748779296875,0.0207366943359375,0.01229095458984375,0.018646240234375,0.003803253173828125,0.00487518310546875,0.00032520294189453125,-0.024444580078125,-0.0245513916015625,0.040802001953125,0.0163726806640625,-0.03167724609375,-0.0169525146484375,-0.0022945404052734375,-0.03985595703125,-0.0211944580078125,0.053497314453125,-0.01190948486328125,-0.024627685546875,-0.0294647216796875,0.01486968994140625,0.03070068359375,0.019927978515625,-0.0182647705078125,0.0238800048828125,-0.046875,0.0123138427734375,0.051116943359375,0.005390167236328125,-0.013641357421875,0.041839599609375,0.0242156982421875,-0.0218963623046875,-0.056793212890625,-0.01434326171875,-0.003429412841796875,-0.0287933349609375,0.0014162063598632812,-0.004405975341796875,0.00386810302734375,-0.0009279251098632812,-0.023529052734375,-0.0020313262939453125,0.0210723876953125,0.014373779296875,0.0174560546875,-0.04547119140625,0.015869140625,0.01236724853515625,-0.015869140625,0.031768798828125,-0.01447296142578125,-0.054840087890625,0.07208251953125,0.015625,0.01407623291015625,-0.023956298828125,0.0212249755859375,-0.02313232421875,-0