INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('dd0a0f2c-ce3f-4c8f-af05-8bb1d3390a7a','c094822a-2476-4aaa-b13f-5026ba0281e7','ada7ec6a-9020-4277-9469-fc0d5d4208a0','ef4aed26-1124-4625-ac16-fb2b674a2514','怡红院',replace('## 位置\n[[大观园]]内，[[贾宝玉]]的住处。\n\n## 去过的经历\n- [[刘姥姥进大观园]]时，[[刘姥姥]]喝多了酒，想去上厕所，一阵乱跑迷了路，闯进怡红院。\n- 她一头倒在[[贾宝玉]]精致的床上呼呼大睡，满屋子酒气。等[[袭人]]回来才发现，悄悄把她叫醒，收拾干净，没惊动别人。\n\n## 整体印象\n陈设精致，是[[贾宝玉]]的居所。\n\n## 关联人物\n[[贾宝玉]]、[[刘姥姥]]、[[袭人]]','\n',char(10)),'[-0.048583984375,0.0408935546875,-0.048431396484375,0.0008955001831054688,-0.01263427734375,0.0009813308715820312,-0.01373291015625,-0.04107666015625,0.01424407958984375,0.0016756057739257812,0.005138397216796875,0.00827789306640625,-0.00994110107421875,-0.00797271728515625,0.0104522705078125,-0.00919342041015625,0.01715087890625,-0.037567138671875,-0.04913330078125,-0.0287933349609375,-0.0210113525390625,0.021392822265625,-0.0236053466796875,-0.0227508544921875,-0.0282135009765625,0.0073394775390625,0.0202484130859375,-0.0010938644409179688,-0.01406097412109375,-0.00423431396484375,0.017303466796875,-0.035888671875,0.027557373046875,0.035125732421875,0.0518798828125,-0.006755828857421875,0.00830841064453125,-0.0640869140625,0.0022602081298828125,0.028656005859375,-0.0018777847290039062,0.044097900390625,-0.0011739730834960938,0.0269927978515625,-0.014678955078125,-0.07275390625,0.0134429931640625,-0.021728515625,-0.044769287109375,0.0282135009765625,0.0160064697265625,0.0170440673828125,-0.01273345947265625,-0.034332275390625,0.0211029052734375,0.051116943359375,-0.0286712646484375,-0.006687164306640625,-0.0037212371826171875,0.00982666015625,-0.015777587890625,-0.016326904296875,0.0135345458984375,0.008209228515625,-0.046661376953125,0.07354736328125,0.009185791015625,0.0198974609375,-0.031524658203125,0.0355224609375,-0.021942138671875,-0.002071380615234375,-0.0232696533203125,0.000568389892578125,-0.008903503