INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('a7068f1b-f558-41d9-8527-e4f5a3997386','c094822a-2476-4aaa-b13f-5026ba0281e7','ada7ec6a-9020-4277-9469-fc0d5d4208a0','66c032cc-0c8c-4045-a3a9-53411e9e24f6','林黛玉',replace('## 基本信息\n- **身份**：[[贾母]]外孙女，[[贾府]]亲戚\n- **与我关系**：无直接关系（《红楼梦》人物）\n- **别名**：无\n\n## 性格与特征\n文雅，爱读书，体弱。\n\n## 关键事件\n- 住[[潇湘馆]]，[[刘姥姥进大观园]]时，[[刘姥姥]]见满屋书，误以为是公子书房。\n- 在[[秋爽斋]]宴席上，[[刘姥姥]]说笑话，她笑岔了气，扶着桌子直哎哟。\n- 在[[栊翠庵]]，[[妙玉]]单独给她用珍藏的梅花雪水泡茶。\n\n## 习惯与喜好\n- 爱读书，住处满是书\n- 与[[贾宝玉]]、[[薛宝钗]]交好\n\n## 关联页面\n- [[大观园]]\n- [[史湘云]]\n- [[牙牌令]]\n','\n',char(10)),'[-0.038482666015625,0.03558349609375,-0.0531005859375,-0.005741119384765625,-0.0225067138671875,-0.003948211669921875,-0.0105743408203125,-0.0036334991455078125,0.01983642578125,-0.004283905029296875,-0.00856781005859375,-0.005992889404296875,-0.042999267578125,0.01824951171875,0.00574493408203125,0.043212890625,-0.032745361328125,-0.02105712890625,-0.018890380859375,-0.006343841552734375,-0.031524658203125,0.026214599609375,0.0135650634765625,-0.032684326171875,0.00606536865234375,0.002490997314453125,-0.03338623046875,-0.0313720703125,0.0355224609375,0.00421142578125,0.001186370849609375,-0.04888916015625,0.04486083984375,0.0033721923828125,0.033447265625,-0.019073486328125,0.022979736328125,-0.0592041015625,-0.005565643310546875,0.01334381103515625,0.00778961181640625,0.03533935546875,0.0179595947265625,0.01001739501953125,-0.0158538818359375,-0.03631591796875,-0.0012683868408203125,-0.0037784576416015625,-0.0479736328125,-0.006561279296875,0.00833892822265625,0.00090789794921875,-0.0017833709716796875,-0.032958984375,-0.030609130859375,0.02325439453125,0.031829833984375,0.0005841255187988281,-0.005680084228515625,0.01788330078125,0.00896453857421875,-0.02398681640625,0.0111846923828125,-0.017791748046875,-0.0268096923828125,0.04766845703125,0.0352783203125,-0.0034580230712890625,-0.0133819580078125,-0.