INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('be35c1e4-76d7-4058-a2b2-82b05c0c85a9','c094822a-2476-4aaa-b13f-5026ba0281e7','ada7ec6a-9020-4277-9469-fc0d5d4208a0','66c032cc-0c8c-4045-a3a9-53411e9e24f6','王熙凤',replace('## 基本信息\n- **身份**：[[贾府]]管家，人称凤姐\n- **与我关系**：无直接关系（《红楼梦》人物）\n- **别名**：凤姐\n\n## 性格与特征\n精明能干，会办事，善于逗[[贾母]]开心。\n\n## 关键事件\n- 第一年[[刘姥姥]]家快饿死上门求助，她接济二十两银子，帮其渡过难关。\n- [[刘姥姥进大观园]]时，与[[鸳鸯]]提前跟[[刘姥姥]]说好，拿她逗[[贾母]]开心。\n- 在[[秋爽斋]]宴席上，给[[刘姥姥]]拿老年四楞象牙镶金筷子，忍着笑继续安排。\n- 宴席继续喝酒时，[[刘姥姥]]要木杯子，她拿出一套十个竹根大套杯，逼着刘姥姥一路喝完一套。\n- 后来[[贾府]]败落，[[刘姥姥]]回来救出她的女儿[[巧姐]]。\n\n## 习惯与喜好\n- 善于操办宴席、安排场面\n\n## 关联页面\n- [[大观园]]\n','\n',char(10)),'[-0.0738525390625,0.034271240234375,-0.0254364013671875,-0.00014257431030273438,-0.04248046875,-0.05804443359375,0.0024738311767578125,0.01168060302734375,-0.006847381591796875,-0.0008573532104492188,-0.00479888916015625,0.007129669189453125,-0.0537109375,0.018310546875,0.01666259765625,0.0312347412109375,-0.0269775390625,-0.02740478515625,-0.0177459716796875,-0.0020732879638671875,-0.06341552734375,0.0135955810546875,-0.034912109375,-0.0209503173828125,-0.0526123046875,0.00632476806640625,-0.0217437744140625,-0.0201568603515625,0.0016841888427734375,0.0100860595703125,-0.01336669921875,-0.051788330078125,-0.02972412109375,0.034912109375,0.041961669921875,-0.02325439453125,-0.057281494140625,-0.07080078125,-0.0051422119140625,0.0426025390625,-0.0128936767578125,0.038848876953125,0.008026123046875,0.017913818359375,-0.01285552978515625,-0.03680419921875,-0.01169586181640625,-0.0106201171875,-0.0228118896484375,-0.00554656982421875,-0.002674102783203125,0.0030364990234375,0.01629638671875,-0.00041222572326660156,0.0187225341796875,0.016082763671875,0.0204620361328125,0.031524658203125,0.0289306640625,0.0207977294921875,-0.012664794921875,0.0237274169921875,-0.00801849365234375,-0.0068359375,-0.0027179718017578125,0.07275390625,0.005153656005859375,