INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('c755fdf7-c0da-4f69-ac87-c606fab5cf93','c094822a-2476-4aaa-b13f-5026ba0281e7','ada7ec6a-9020-4277-9469-fc0d5d4208a0','66c032cc-0c8c-4045-a3a9-53411e9e24f6','妙玉',replace('## 基本信息\n- **身份**：[[栊翠庵]]修行者\n- **与我关系**：无直接关系（《红楼梦》人物）\n- **别名**：无\n\n## 性格与特征\n清高，讲究，爱洁。\n\n## 关键事件\n- [[刘姥姥进大观园]]时，拿出好茶招待众人：给[[贾母]]用旧年雨水泡的老君眉，单独给[[贾宝玉]]、[[薛宝钗]]、[[林黛玉]]用珍藏的梅花雪水。\n- 拿一个粗茶杯给[[刘姥姥]]，刘姥姥喝完，她嫌杯子被用过，打算直接扔掉，[[贾宝玉]]劝她，把杯子送给刘姥姥。\n\n## 习惯与喜好\n- 讲究茶道，珍藏梅花雪水、旧年雨水\n- 住在[[栊翠庵]]\n\n## 关联页面\n- [[大观园]]\n','\n',char(10)),'[-0.037017822265625,0.00846099853515625,-0.06622314453125,-0.020050048828125,-0.0266876220703125,-0.039306640625,-0.01448822021484375,-0.03564453125,-0.00441741943359375,-0.0038089752197265625,0.004978179931640625,-0.0041046142578125,-0.0328369140625,0.009521484375,0.031005859375,0.04180908203125,-0.034423828125,-0.00897979736328125,-0.01165771484375,-0.01531219482421875,-0.0238189697265625,0.047027587890625,0.002902984619140625,-0.033599853515625,0.0117645263671875,0.006114959716796875,-0.043914794921875,-0.040496826171875,0.054656982421875,0.01114654541015625,-0.0249176025390625,-0.01032257080078125,-0.0012063980102539062,0.0172576904296875,0.0026092529296875,-0.0233306884765625,0.01355743408203125,-0.050689697265625,0.01129913330078125,0.04254150390625,0.0247650146484375,-0.016998291015625,0.038177490234375,-0.0005879402160644531,-0.01456451416015625,-0.050537109375,-0.0080413818359375,0.0059356689453125,-0.00844573974609375,0.01068115234375,0.0165252685546875,0.0037364959716796875,-0.0016107559204101562,-0.0033016204833984375,0.01371002197265625,0.01389312744140625,0.0243072509765625,0.013702392578125,-0.01380157470703125,0.01593017578125,0.00408172607421875,0.0206451416015625,0.0153656005859375,-0.004352569580078125,-0.05963134765625,0.061248779296875,0.01021575927734375,-0.0006079673767089844,0.00020825862884521484,0.