INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('ff16a64c-c11b-4a62-a43b-e26a53e2ac75','c094822a-2476-4aaa-b13f-5026ba0281e7','ada7ec6a-9020-4277-9469-fc0d5d4208a0','ef4aed26-1124-4625-ac16-fb2b674a2514','贾府',replace('## 位置\n（资料未详述具体位置）\n\n## 去过的经历\n- 第一年[[刘姥姥]]家快饿死，上门求助，[[王熙凤]]接济二十两银子。\n- 第二年秋收，[[刘姥姥]]挑瓜果蔬菜来道谢，[[贾母]]留她多住几天，带她游览[[大观园]]。\n- 几天游玩结束，[[刘姥姥]]告辞，众人送她布匹、衣服、药材、银子、吃食一大堆。\n\n## 整体印象\n富贵豪门，生活奢靡。曹雪芹借[[刘姥姥]]一双乡下人的眼睛写出其奢华，对比底层穷苦，埋下将来衰败的伏笔。后来果然败落。\n\n## 关联人物\n[[贾母]]、[[王熙凤]]、[[贾宝玉]]、[[刘姥姥]]、[[巧姐]]\n\n## 关联页面\n- [[林黛玉]]\n- [[薛宝钗]]\n- [[探春]]\n- [[惜春]]\n- [[史湘云]]\n','\n',char(10)),'[-0.088134765625,0.04766845703125,-0.0345458984375,-0.00742340087890625,-0.0174713134765625,-0.0111541748046875,0.0133819580078125,0.036895751953125,-0.026763916015625,0.001827239990234375,0.0017194747924804688,0.0019683837890625,-0.033935546875,0.01617431640625,0.001041412353515625,0.04412841796875,0.0245819091796875,-0.030242919921875,-0.0292510986328125,-0.006282806396484375,-0.043853759765625,0.0159759521484375,-0.0072174072265625,-0.039093017578125,-0.058319091796875,-0.00949859619140625,-0.0261077880859375,-0.018951416015625,-0.0222015380859375,0.0200347900390625,-0.008575439453125,-0.033843994140625,0.034393310546875,0.033233642578125,0.035308837890625,-0.01922607421875,-0.0011339187622070312,-0.0546875,-0.0016498565673828125,0.0540771484375,0.0077972412109375,0.0341796875,0.0028743743896484375,0.0465087890625,-0.0202789306640625,-0.050201416015625,-0.00891876220703125,-0.0205841064453125,-0.04962158203125,0.0202789306640625,-0.00371551513671875,-0.0161895751953125,0.0012273788452148438,-0.024261474609375,0.004695892333984375,0.002056121826171875,-0.024383544921875,0.01515960693359375,-0.00665283203125,-0.00579071044921875,0.00890350341796875,-0.01358795166015625,-0.011993408203125,0.002346038818359375,-0.0208740234375,0.09417724609375,0.0184326171875,-0.0030498504638671875,