INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('f0fb92de-2ab5-42c5-92f4-6c0311719115','5c7a5c04-949e-49bf-b099-754a117a66fc','08717303-45fb-4161-8b84-c2540337cdcb','b147b224-7469-4561-b088-7b85ff08c43a','刘姥姥',replace('## 基本信息\n- **身份**：乡下贫苦老太太，女婿家与贾府沾一点远亲\n- **与我关系**：贾府的远亲客人，[[贾母]]的座上宾\n- **别名**：母蝗虫（[[林黛玉]]戏称）\n\n## 性格与特征\n质朴幽默、不卑不亢、心里通透。愿意配合[[王熙凤]]、[[鸳鸯]]哄[[贾母]]开心，用乡下土话逗乐众人。\n\n## 关键事件\n- 第一年家里快饿死，带外孙[[板儿]]上门求助，[[王熙凤]]接济二十两银子渡过难关。\n- 第二年秋收，挑着自家种的瓜果蔬菜专程来贾府道谢，参与 [[刘姥姥进大观园]]。\n- 在[[秋爽斋]]宴席上说“老刘，老刘，食量大如牛；吃个老母猪，不抬头！”引爆全场大笑。\n- 在[[栊翠庵]]用粗茶杯喝茶，[[妙玉]]嫌杯子被她用过要扔，[[贾宝玉]]劝妙玉把杯子送给她。\n- 醉后迷路闯进[[怡红院]]，倒在[[贾宝玉]]床上大睡，被[[袭人]]悄悄叫醒收拾。\n- 后来贾府败落，刘姥姥回来救出了王熙凤的女儿[[巧姐]]。\n\n## 习惯与喜好\n乡下人本色，说话用土话俚语，如“大火烧了毛毛虫”“花儿落了结个大倭瓜”。\n\n## 关联页面\n- [[大观园]]\n- [[潇湘馆]]\n- [[史湘云]]\n','\n',char(10)),'[-0.082763671875,0.043792724609375,-0.0270843505859375,-0.0058135986328125,-0.038238525390625,-0.01617431640625,-0.0009937286376953125,0.0135650634765625,-0.0207977294921875,0.00429534912109375,-0.032745361328125,0.003917694091796875,-0.0682373046875,0.01611328125,0.01043701171875,0.0228118896484375,-0.0260162353515625,-0.0205230712890625,-0.03045654296875,0.0038890838623046875,-0.045166015625,0.0198822021484375,-0.022796630859375,-0.0293121337890625,-0.020538330078125,0.0093231201171875,0.004253387451171875,-0.031036376953125,-0.0009427070617675781,0.0054473876953125,-0.0008959770202636719,-0.01898193359375,-0.002910614013671875,0.002780914306640625,0.0242462158203125,-0.0014867782592773438,0.0001322031021118164,-0.0357666015625,-0.00016486644744873047,0.039398193359375,-0.00444793701171875,0.051361083984375,0.0150604248046875,0.035797119140625,-0.022216796875,-0.042236328125,-0.01435089111328125,-0.015167236328125,-0.006351470947265625,0.00223541259765625,-0.0249786376953125,-0.0030765533447265625,0.021087646484375,-0.032379150390625,-0.01551055908203125,0.0007448196411132812,0.02984619140625,0.04159