INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('24c04e24-55f0-404b-bab0-fe4750865cbc','5c7a5c04-949e-49bf-b099-754a117a66fc','08717303-45fb-4161-8b84-c2540337cdcb','0cfd2ffb-e829-4979-86bc-df5fb058ec26','大观园',replace('## 位置\n贾府内为元妃省亲所建的园林，园内有[[潇湘馆]]、[[秋爽斋]]、[[栊翠庵]]、[[怡红院]]等多处院落。\n\n## 去过的经历\n[[刘姥姥]]二进荣国府时，[[贾母]]带她与[[贾宝玉]]、[[林黛玉]]、[[薛宝钗]]、[[贾探春]]等一众小姐游览大观园、摆宴席招待，即 [[刘姥姥进大观园]]。\n\n## 整体印象\n奢华铺陈，是富贵大家族生活的集中体现。曹雪芹借[[刘姥姥]]一双乡下人的眼睛写出园中奢华，对比底层穷苦与豪门奢靡，埋下贾府将来衰败的伏笔。\n\n## 关联人物\n[[贾母]]、[[贾宝玉]]、[[林黛玉]]、[[薛宝钗]]、[[贾探春]]、[[刘姥姥]]、[[王熙凤]]、[[鸳鸯]]','\n',char(10)),'[-0.061767578125,0.035369873046875,-0.0628662109375,-0.003726959228515625,-0.0015916824340820312,0.0167999267578125,-0.034454345703125,0.0175933837890625,-0.01488494873046875,0.003826141357421875,-0.009765625,0.0098724365234375,-0.0028591156005859375,0.03668212890625,0.01520538330078125,0.0032958984375,0.0231475830078125,-0.00279998779296875,0.0266265869140625,-0.0231781005859375,-0.0311737060546875,0.0159759521484375,0.00626373291015625,-0.0299530029296875,-0.05029296875,0.0166168212890625,-0.0230560302734375,-0.005695343017578125,-0.01617431640625,0.01422119140625,-0.01381683349609375,-0.057586669921875,0.02203369140625,0.0281982421875,0.034454345703125,-0.005321502685546875,-0.0018634796142578125,-0.081298828125,-0.001251220703125,0.03778076171875,0.00753021240234375,0.0177459716796875,0.0164947509765625,0.0299530029296875,-0.01181793212890625,-0.0677490234375,0.00829315185546875,-0.0266265869140625,-0.05810546875,0.03009033203125,-0.004688262939453125,0.004680633544921875,-0.01220703125,-0.043701171875,-0.018341064453125,0.027008056640625,-0.05303955078125,0.0192108154296875,-0.0115966796875,0.0019521713256835938,0.0038013458251953125,-0.0241546630859375,-0.01544189453125,0.0202484130859375,-0.0102691650390625,0.0797119140625,0.013946533203125,0.01396942138671875,-0.0288543701171875,-0.00823211669921875,-0.0380