INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('16523f37-e7a3-4d34-b9b0-a89df273cc74','5c7a5c04-949e-49bf-b099-754a117a66fc','08717303-45fb-4161-8b84-c2540337cdcb','0cfd2ffb-e829-4979-86bc-df5fb058ec26','秋爽斋',replace('## 位置\n[[大观园]]内，[[贾探春]]的住处。\n\n## 去过的经历\n[[刘姥姥进大观园]]时宴席摆在秋爽斋，是最经典的笑场片段发生地。开饭前[[鸳鸯]]、[[王熙凤]]安排好，给[[刘姥姥]]拿一双老年四楞象牙镶金筷子，沉甸甸很不好拿。刘姥姥站起来大声说“老刘，老刘，食量大如牛；吃个老母猪，不抬头！”引爆全场大笑。\n\n## 整体印象\n宴席场所，见证刘姥姥逗乐众人的名场面。\n\n## 关联人物\n[[贾探春]]、[[刘姥姥]]、[[王熙凤]]、[[鸳鸯]]、[[贾母]]','\n',char(10)),'[-0.03369140625,0.05670166015625,-0.064697265625,0.0175018310546875,-0.04034423828125,-0.003528594970703125,0.0035305023193359375,0.0321044921875,-0.0178375244140625,-0.0067138671875,-0.010101318359375,0.031829833984375,-0.0335693359375,0.016815185546875,0.0158538818359375,-0.022186279296875,0.0179443359375,-0.005283355712890625,-0.00909423828125,-0.016265869140625,-0.07666015625,0.007762908935546875,-0.021942138671875,0.024078369140625,-0.004467010498046875,0.0015811920166015625,-0.02069091796875,-0.0146331787109375,0.0253448486328125,-0.0097198486328125,0.01006317138671875,-0.0211029052734375,0.0095977783203125,0.019989013671875,0.044219970703125,-0.024017333984375,-0.0220489501953125,-0.043609619140625,-0.01371002197265625,0.0110015869140625,0.0165252685546875,0.038665771484375,-0.00363922119140625,-0.003780364990234375,-0.041961669921875,-0.06402587890625,-0.0239410400390625,-0.013946533203125,-0.018157958984375,0.038543701171875,-0.0082244873046875,0.028472900390625,0.02801513671875,0.0045928955078125,0.0169677734375,0.0224609375,0.00484466552734375,0.0190582275390625,-0.05780029296875,-0.002197265625,0.034149169921875,-0.016448974609375,-0.022125244140625,-0.0138397216796875,-0.0274505615234375,0.08001708984375,0.048736572265625,0.03887939453125,-0.0159759521484375,0.0096893310546875,-0.0185394287109375,0.00954437255859375,0.0340576171875,-0.0018291473388671875,-0.001778602600