INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('4e87a072-54ff-456a-8a9f-eb150352646e','5c7a5c04-949e-49bf-b099-754a117a66fc','08717303-45fb-4161-8b84-c2540337cdcb','0cfd2ffb-e829-4979-86bc-df5fb058ec26','栊翠庵',replace('## 位置\n[[大观园]]内，[[妙玉]]的修行处。\n\n## 去过的经历\n[[刘姥姥进大观园]]时一行人来到栊翠庵。[[妙玉]]清高，拿出好茶招待众人：给[[贾母]]用旧年雨水泡的老君眉；单独给[[贾宝玉]]、[[薛宝钗]]、[[林黛玉]]用珍藏的梅花雪水。妙玉拿一个粗茶杯给[[刘姥姥]]，刘姥姥喝完，妙玉嫌杯子被她用过打算直接扔掉，宝玉劝她，把杯子送给刘姥姥。\n\n## 整体印象\n清雅之地，妙玉的清高与刘姥姥的质朴在此形成鲜明对照。\n\n## 关联人物\n[[妙玉]]、[[刘姥姥]]、[[贾母]]、[[贾宝玉]]、[[薛宝钗]]、[[林黛玉]]','\n',char(10)),'[-0.035675048828125,0.019866943359375,-0.07061767578125,-0.0285797119140625,-0.0129547119140625,-0.0262603759765625,-0.0290985107421875,-0.0225372314453125,0.00815582275390625,-0.021209716796875,0.0159149169921875,-0.00661468505859375,-0.00635528564453125,0.0217437744140625,0.01690673828125,0.0131683349609375,0.00643157958984375,0.00684356689453125,-0.005733489990234375,-0.0248565673828125,-0.0205841064453125,0.04345703125,0.015716552734375,-0.0302734375,-0.0211334228515625,0.0011377334594726562,-0.045196533203125,-0.0211029052734375,0.05291748046875,-0.012420654296875,-0.0220184326171875,-0.02923583984375,0.012359619140625,0.035858154296875,0.019287109375,-0.01617431640625,0.020660400390625,-0.045989990234375,0.01444244384765625,0.048858642578125,0.0015401840209960938,-0.0141143798828125,0.041168212890625,0.0200653076171875,-0.0215606689453125,-0.056243896484375,-0.01290130615234375,-0.0006489753723144531,-0.0306549072265625,0.004535675048828125,-0.0016317367553710938,0.0009746551513671875,0.001003265380859375,-0.0263519287109375,-0.0010662078857421875,0.021636962890625,0.0153961181640625,0.017425537109375,-0.050445556640625,0.01238250732421875,0.01085662841796875,-0.01169586181640625,0.027801513671875,-0.0134429931640625,-0.05828857421875,0.07086181640625,0.01461029052734375,0.01554107666015625,-0.0246124267578125,0.019805908203125,-0.0228576660