INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('fed67813-f6a7-4e46-bc09-38656d604af7','5c7a5c04-949e-49bf-b099-754a117a66fc','08717303-45fb-4161-8b84-c2540337cdcb','0cfd2ffb-e829-4979-86bc-df5fb058ec26','怡红院',replace('## 位置\n[[大观园]]内，[[贾宝玉]]的住处。\n\n## 去过的经历\n[[刘姥姥进大观园]]时，[[刘姥姥]]喝多了酒，想去上厕所，一阵乱跑迷了路，闯进怡红院，一头倒在宝玉精致的床上呼呼大睡，满屋子酒气。等[[袭人]]回来才发现，悄悄把她叫醒，收拾干净，没惊动别人。\n\n## 整体印象\n精致讲究，与刘姥姥的乡下身份形成强烈反差。\n\n## 关联人物\n[[贾宝玉]]、[[刘姥姥]]、[[袭人]]','\n',char(10)),'[-0.051361083984375,0.052520751953125,-0.043548583984375,-0.001667022705078125,-0.0121612548828125,-0.0016078948974609375,-0.0172882080078125,-0.033111572265625,0.0172882080078125,-0.0021343231201171875,-0.00557708740234375,0.01187896728515625,-0.0183868408203125,-0.00910186767578125,0.0234527587890625,-0.00824737548828125,0.00980377197265625,-0.044952392578125,-0.056427001953125,-0.0308837890625,-0.02001953125,0.0202789306640625,-0.0266265869140625,-0.0161590576171875,-0.0280303955078125,0.0107574462890625,0.022796630859375,-0.005001068115234375,-0.01380157470703125,-0.00799560546875,0.0089263916015625,-0.0360107421875,0.024993896484375,0.03125,0.043487548828125,0.0021209716796875,0.01415252685546875,-0.0548095703125,0.0032138824462890625,0.039398193359375,0.002948760986328125,0.045654296875,-0.002513885498046875,0.02764892578125,-0.01806640625,-0.0662841796875,0.0116119384765625,-0.022705078125,-0.036956787109375,0.03704833984375,0.015716552734375,0.011688232421875,-0.006572723388671875,-0.0253753662109375,0.0182037353515625,0.037933349609375,-0.02081298828125,-0.0011129379272460938,-0.0101165771484375,0.01064300537109375,-0.017547607421875,-0.004596710205078125,0.007114410400390625,0.0144195556640625,-0.03533935546875,0.07952880859375,0.0079193115234375,0.01678466796875,-0.0305633544921875,0.030975341796875,-0.0197296142578125,-0.0017118453979492188,-0.01141357421875,0.0009713172912597656,-0.005146026611328125,0.00838