INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('91510dd5-4278-4e4f-8b6f-3af06826ae9f','2b432e1e-c7c5-4690-8ecb-23e8f382b018','08717303-45fb-4161-8b84-c2540337cdcb',NULL,'组件库统一重构方案',replace('## 背景\n\n在 [[MyDiary前端重构项目]] 中，原有页面架构存在历史代码冗余、样式不统一、复用率低等长期遗留问题。\n\n## 决策内容\n\n放弃局部修补优化方案，采用组件库统一重构方案：\n\n- 将项目全部弹窗、模态框统一接入自定义 Modal 规范体系\n- 遵循统一入参、回调、显隐逻辑\n- 彻底消灭碎片化写法\n\n## 决策理由\n\n局部修补无法根治碎片化写法问题，统一重构可以从根本上解决样式不统一和复用率低的问题。\n\n## 关联\n\n- 所属项目：[[MyDiary前端重构项目]]','\n',char(10)),'[-0.01483154296875,-0.0064239501953125,-0.0328369140625,-0.0009388923645019531,-0.0218658447265625,-0.0716552734375,0.022918701171875,0.0198211669921875,0.0217742919921875,0.015838623046875,-0.01678466796875,-0.01285552978515625,0.02239990234375,0.02349853515625,-0.00969696044921875,-0.01558685302734375,0.04681396484375,0.0288238525390625,0.036376953125,0.0248565673828125,-0.007190704345703125,-0.016021728515625,0.033599853515625,-0.0250701904296875,-0.031524658203125,-0.0135955810546875,-0.00628662109375,0.0303955078125,0.0185546875,0.049530029296875,0.01520538330078125,0.005558013916015625,0.069580078125,-0.018157958984375,-0.04290771484375,-0.045166015625,0.043243408203125,0.007526397705078125,-0.01187896728515625,0.0266265869140625,-0.0303192138671875,-0.0017194747924804688,0.01433563232421875,-0.0127716064453125,0.0217742919921875,-0.027069091796875,-0.0143280029296875,-0.0193634033203125,-0.0187835693359375,0.0118408203125,-0.0416259765625,-0.04339599609375,0.07232666015625,-0.06597900390625,0.00677490234375,0.03228759765625,-0.03326416015625,-0.0263671875,-0.01666259765625,0.0236663818359375,-0.0261688232421875,-0.00478363037109375,0.034027099609375,0.017608642578125,-0.004795074462890625,0.0216217041015625,0.001964569091796875,0.036712646484375,-0.00412750244140625,-0.02374267578125,-0.002685546875,-0.006305694580078125,-0.012176513671875,-0.0362548828125,-0.049774169921875,0.01049041748