INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('6a250fd8-f86a-4529-9d03-ad05b2908636','c208fdd5-cc9e-4775-8355-173eb418f19e','08717303-45fb-4161-8b84-c2540337cdcb','ab246b1f-2daa-4e74-ba19-6815f7f83199','MyDiary前端重构迭代项目',replace('## 目标与范围\n对原有老旧页面架构进行解耦，统一弹窗组件、表单组件、路由权限体系，解决历史代码冗余、样式不统一、复用率低等长期遗留问题。项目周期三周，涉及前端重构、组件标准化、交互规范统一、兼容性回归测试四大工作模块。\n\n## 参与人\n资料中未明确列出具体参与人，由本人主导技术方案决策与项目推进管理。\n\n## 里程碑\n- 前期：技术方案决策（组件库统一重构方案、路由集中式配置方案）\n- 推进期：小迭代高频验收，每日对齐组件开发进度\n- 交付期：全量回归测试，分支隔离分批合并上线\n\n## 风险与问题\n- 重构导致的功能回归风险 → 确定全量回归测试策略，所有旧功能逐条验证\n- 兼容性问题 → 优先保证主流浏览器适配，移动端做渐进式兼容\n- 代码合并风险 → 分支隔离、分批合并机制\n\n## 当前进展\n已成功完成架构轻量化升级，为后续功能迭代奠定统一技术基线。相关技术决策与流程经验已沉淀归档。\n\n## 关联页面\n- [[组件库统一重构方案]]\n- [[路由集中式配置与权限前置拦截]]\n- [[小迭代高频验收模式]]\n- [[兼容性适配策略]]\n- [[全量回归测试策略]]\n- [[分支隔离分批合并机制]]\n','\n',char(10)),'[-0.01367950439453125,-0.0157012939453125,-0.0245208740234375,-0.002834320068359375,-0.01010894775390625,-0.0281829833984375,0.007129669189453125,-0.009674072265625,0.0211639404296875,0.034149169921875,-0.034820556640625,0.0157318115234375,0.0035190582275390625,0.00479888916015625,-0.01303863525390625,-0.0146026611328125,0.05938720703125,0.006130218505859375,0.038421630859375,0.0160675048828125,-0.01201629638671875,-0.02740478515625,0.0078277587890625,-0.0129547119140625,0.01224517822265625,-0.006153106689453125,0.0207366943359375,0.0058135986328125,0.0213470458984375,0.05389404296875,0.0172576904296875,0.00006657838821411133,0.035888671875,-0.0280914306640625,-0.016082763671875,-0.00930023193359375,0.02056884765625,-0.01132965087890625,-0.032470703125,0.04638671875,-0.041839599609375,-0.01454925537109375,-0.01145172119140625,-0.01092529296875,0.0111541748046875,-0.0303802490234375,0.0025539398193359375,-0.0197906494140625,-0.01532745361328125,-0.0303497314453125,-0.0187225341796875,-0.040802001953125,0.038330078125,-0.0753173828125,0.01224517822265625,0.0075531005859375,-0.02198791503906