INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('f5f2fb13-0452-482b-94f9-e240fab91306','c208fdd5-cc9e-4775-8355-173eb418f19e','08717303-45fb-4161-8b84-c2540337cdcb','24cc14dd-8764-43b3-a6c7-7ba5b8f57bf2','组件库统一重构方案',replace('## 背景\n[[MyDiary前端重构迭代项目]]中，原有老旧页面架构存在历史代码冗余、样式不统一、复用率低等长期遗留问题，弹窗、模态框写法碎片化。\n\n## 可选方案\n1. 局部修补优化方案\n2. 组件库统一重构方案\n\n## 利弊分析\n- 局部修补：改动小、风险低，但无法根治碎片化写法，技术债会持续累积\n- 组件库统一重构：一次性投入大，但能彻底消灭碎片化写法，建立统一技术基线\n\n## 最终选择\n采用组件库统一重构方案，将项目全部弹窗、模态框统一接入自定义 Modal 规范体系，遵循统一入参、回调、显隐逻辑，彻底消灭碎片化写法。\n\n## 后续跟踪\n为后续功能迭代奠定统一技术基线，相关经验用于同类前端重构项目参考复用。','\n',char(10)),'[-0.020263671875,0.001056671142578125,-0.0299835205078125,0.00131988525390625,-0.007793426513671875,-0.074951171875,0.0238037109375,0.034423828125,0.0163726806640625,0.011474609375,-0.01233673095703125,-0.0202789306640625,0.026123046875,0.0210723876953125,-0.00782012939453125,-0.013153076171875,0.031280517578125,0.033599853515625,0.02569580078125,0.0241241455078125,0.002376556396484375,-0.0146331787109375,0.039581298828125,-0.0257415771484375,-0.0233306884765625,-0.00881195068359375,-0.00641632080078125,0.03375244140625,0.008453369140625,0.044708251953125,0.02130126953125,-0.0028514862060546875,0.05950927734375,-0.004619598388671875,-0.03179931640625,-0.045989990234375,0.048553466796875,0.0022182464599609375,-0.0203857421875,0.031951904296875,-0.034088134765625,0.00807952880859375,0.017181396484375,-0.00981903076171875,0.01459503173828125,-0.021392822265625,-0.00968170166015625,-0.01788330078125,-0.00907135009765625,-0.00890350341796875,-0.03216552734375,-0.0513916015625,0.05908203125,-0.0577392578125,0.00159454345703125,0.03753662109375,-0.034912109375,-0.0296478271484375,-0.02685546875,0.01375579833984375,-0.031402587890625,0.0003387928009033203,0.0487060546875,0.0198974609375,-0.0020046234130859375,0.028564453125,0.007770538330078125,0.02996826171875,-0.0098114013671875,-0.038055419921875,-0.000