INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('9fdc5c5f-eda3-460a-bd68-148981223473','c208fdd5-cc9e-4775-8355-173eb418f19e','08717303-45fb-4161-8b84-c2540337cdcb','24cc14dd-8764-43b3-a6c7-7ba5b8f57bf2','小迭代高频验收模式',replace('## 背景\n[[MyDiary前端重构迭代项目]]推进过程中，需要避免UI不一致、逻辑重复等问题导致技术债务累积。\n\n## 可选方案\n1. 传统阶段性验收\n2. 小迭代高频验收模式\n\n## 利弊分析\n- 阶段性验收：反馈周期长，问题容易积压\n- 小迭代高频验收：每日对齐进度，问题即时发现即时整改\n\n## 最终选择\n采用小迭代高频验收模式，每日对齐组件开发进度，对UI不一致、逻辑重复的问题即时叫停整改，避免技术债务累积。\n\n## 后续跟踪\n作为项目管理经验沉淀，用于后续同类前端重构项目参考复用。','\n',char(10)),'[-0.0673828125,-0.01071929931640625,-0.00846099853515625,-0.006435394287109375,-0.01364898681640625,-0.02239990234375,0.0241241455078125,0.044921875,0.00991058349609375,0.02679443359375,0.007350921630859375,-0.0018749237060546875,0.006534576416015625,0.037841796875,-0.03570556640625,-0.0140533447265625,-0.0167694091796875,-0.00940704345703125,0.045440673828125,0.0074462890625,-0.01294708251953125,0.00615692138671875,0.035125732421875,-0.005939483642578125,-0.028076171875,0.00762939453125,-0.01183319091796875,0.028167724609375,0.038238525390625,0.09454345703125,-0.00299835205078125,0.0179443359375,0.030975341796875,-0.01861572265625,-0.041046142578125,-0.0233917236328125,0.0081634521484375,-0.0245208740234375,-0.0214996337890625,0.04925537109375,0.0018701553344726562,0.0129241943359375,0.032867431640625,-0.016632080078125,0.017364501953125,-0.01406097412109375,0.001926422119140625,-0.014373779296875,-0.0166778564453125,-0.0028095245361328125,-0.020660400390625,-0.0360107421875,0.0199432373046875,-0.05926513671875,0.003124237060546875,0.054595947265625,-0.0145263671875,-0.032257080078125,-0.032501220703125,0.0380859375,-0.01137542724609375,0.0023632049560546875,0.03948974609375,0.01126861572265625,0.0233154296875,0.01995849609375,0.0021648406982421875,0.032562255859375,0.0013246536254882812,-0.051361083984375,0.0081024169921875,-0.012420654296875,-0.028747558593