INSERT INTO "wiki_pages" ("id","kb_id","user_id","category_id","title","content","vector","source_ids","is_system","created_at","updated_at","summary") VALUES('26379ac6-5466-441b-81f6-7d35a5582628','0756bf82-f569-46a7-918d-185dc1e25d4b','08717303-45fb-4161-8b84-c2540337cdcb','41000db8-784e-434e-9534-8a5c846030d2','稀疏注意力机制',replace('## 主题概述\n解决 Transformer 二次方复杂度瓶颈的主流路线之一。核心思路：并非每个 token 都需要「看到」序列中所有其他 token，通过可学习的稀疏模式或局部窗口 + 全局锚点组合，在保持表达力的同时将计算量从 O(n²) 降至近似 O(n·√n) 或 O(n·log n)。\n\n## 关联人物\n（资料未提及具体人物）\n\n## 关联事件\n- 2025年10月，[[DeepSeek 长文本实验模型]]在此方向推进\n- 斯坦福 SambaNova 合作研究在此方向推进\n- 支撑 [[2025年10月AI三线并进]] 中的长上下文效率突破\n\n## 资料来源\n2025年10月技术趋势资料（用户上传）\n\n## 我的观点\n稀疏注意力使百万 token 级文档处理进入实用阶段，是长上下文效率突破的关键技术。','\n',char(10)),'[-0.0204315185546875,-0.02508544921875,-0.0034503936767578125,-0.007511138916015625,-0.020904541015625,-0.0234375,0.0223388671875,0.00980377197265625,-0.00453948974609375,0.0196380615234375,-0.045867919921875,-0.034881591796875,-0.00435638427734375,0.033905029296875,0.0027751922607421875,0.004283905029296875,0.001644134521484375,-0.04241943359375,0.0240478515625,0.0229949951171875,-0.027740478515625,0.0307769775390625,-0.013519287109375,0.0229339599609375,-0.0151519775390625,0.04931640625,-0.01824951171875,-0.0292205810546875,-0.01141357421875,0.05804443359375,0.0080413818359375,-0.00002092123031616211,-0.0120391845703125,-0.03997802734375,-0.0180816650390625,-0.0160064697265625,0.021820068359375,-0.05450439453125,-0.0269317626953125,0.023895263671875,0.004718780517578125,-0.0217132568359375,0.036834716796875,-0.014862060546875,0.0648193359375,-0.0093841552734375,0.0010089874267578125,-0.02557373046875,0.004451751708984375,0.019805908203125,-0.05615234375,-0.03692626953125,0.00470733642578125,-0.01412200927734375,-0.0135345458984375,-0.0240631103515625,-0.0265960693359375,-0.03131103515625,-0.029205322265625,-0.0214080810546875,-0.021881103515625,0.047637939453125,-0.005847930908203125,0.00910186767578125,0.040618896484375,0.03936767578125,-0.0006422996