INSERT INTO "diaries" ("id","user_id","date","template_id","title","mood_id","tags","weather","blocks","created_at","updated_at","deleted_at","capsule_unlock_at","wallpaper","show_lines") VALUES('cba0e144-a74b-4b47-8f56-a91382a5a31c','08717303-45fb-4161-8b84-c2540337cdcb','2026-10-10','diary','📖认知觉醒解读','calm','[]','{"temp":21,"description":"晴","icon":"☀️"}','[{"id":"b_mv1ob0qi_0qi5z","kind":"text","content":"【小麦建议】\n《认知觉醒》是周岭写的一本关于个人成长和方法论的书。它主要讲的是如何通过改变底层思维模式，摆脱盲目焦虑，实现自我掌控。\n\n书里核心讲了五个底层概念：\n1.  **元认知**：跳出自我去审视自我，这是认知升级的起点。\n2.  **专注力**：刻意练习专注，让注意力停留在当下，而不是被情绪牵着走。\n3.  **刻意练习**：通过“舒适区边缘”的练习，配合反馈和重复，来掌握新技能。\n4.  **情绪本能**：理解情绪是身体发出的信号，学会与情绪共存，利用本能而非对抗本能。\n5.  **行动策略**：强调“最小行动力”，通过具体的行动来带动思考，而不是光想不做。\n\n这本书很务实，适合想提升思维深度、解决内耗和拖延症的朋友阅读。如果你最近也在思考怎么让行动更落地，看看这本可能会很有帮助。 📖✨"}]',1791593621618,1791593621618,NULL,NULL,'/papers/mist-mountain.jpg',0);
