INSERT INTO "wiki_debug_log" ("id","ts","tag","msg","data") VALUES('fd96427d-47b4-420a-90fc-ca126443245b',1790784716339,'ingest','AI_RAW','{"batch":0,"preview":"{\n  \"pages\": [\n    {\n      \"title\": \"家常红烧肉\",\n      \"category_slug\": \"caipu\",\n      \"action\": \"create\",\n      \"summary\": \"带皮五花肉炒糖色后小火慢炖，肥而不腻、红亮软糯\",\n      \"content\": \"## 难度与耗时\\n- **难度**：中等（需要炒糖色）\\n- **耗时**：约 1.5 小时（焯水约 6 分钟，慢炖 60 分钟，喜欢更烂可延长到 80 分钟）\\n\\n## 食材\\n- 带皮[[五花肉]] 750g\\n- [[生姜]] 6 片\\n- 大葱段\\n- [[冰糖]] 15g\\n- 八角 1 个\\n- 桂皮 小段\\n- 香叶 2 片\\n- 生抽 2 勺\\n- 老抽 半勺\\n- 料酒 2 勺\\n- 盐 少许\\n\\n## 步骤\\n1. 五花肉切 3 厘米方块，冷水下锅，放姜片 + 1 勺料酒，大火煮开，撇掉浮沫，继续煮 3 分钟捞出，温水冲洗干净。（不要冷水冲热肉，肉质会收紧发柴）\\n2. 锅里放一点点油，小火下 [[冰糖]] 炒糖色：慢慢熬到冰糖融化变成"}');
INSERT INTO "wiki_debug_log" ("id","ts","tag","msg","data") VALUES('1f839355-2750-4aeb-83f7-d37d9076428b',1790784716397,'ingest','PARSE_FAIL','{"batch":0,"rawLen":690,"raw":"{\n  \"pages\": [\n    {\n      \"title\": \"家常红烧肉\",\n      \"category_slug\": \"caipu\",\n      \"action\": \"create\",\n      \"summary\": \"带皮五花肉炒糖色后小火慢炖，肥而不腻、红亮软糯\",\n      \"content\": \"## 难度与耗时\\n- **难度**：中等（需要炒糖色）\\n- **耗时**：约 1.5 小时（焯水约 6 分钟，慢炖 60 分钟，喜欢更烂可延长到 80 分钟）\\n\\n## 食材\\n- 带皮[[五花肉]] 750g\\n- [[生姜]] 6 片\\n- 大葱段\\n- [[冰糖]] 15g\\n- 八角 1 个\\n- 桂皮 小段\\n- 香叶 2 片\\n- 生抽 2 勺\\n- 老抽 半勺\\n- 料酒 2 勺\\n- 盐 少许\\n\\n## 步骤\\n1. 五花肉切 3 厘米方块，冷水下锅，放姜片 + 1 勺料酒，大火煮开，撇掉浮沫，继续煮 3 分钟捞出，温水冲洗干净。（不要冷水冲热肉，肉质会收紧发柴）\\n2. 锅里放一点点油，小火下 [[冰糖]] 炒糖色：慢慢熬到冰糖融化变成枣红色、冒细密小泡，立刻倒入五花肉快速翻炒，让肉块均匀裹上糖色。\\n3. 放葱姜、八角、桂皮、香叶，翻炒出香味，加料酒、生抽、老抽翻炒上色。倒入开水，没过肉块（必须开水！）。\\n4. 大火烧开转最小火，盖上锅盖慢炖 60 分钟。\\n5. 开盖加适量盐调味，开大火收汁，汤汁浓稠裹满肉就关火。\\n\\n## 小贴士\\n- 想更清爽可以炖好后撇浮油；喜欢口感更烂可以延长到 80 分钟。"}');
