INSERT INTO "wiki_debug_log" ("id","ts","tag","msg","data") VALUES('5f8115fa-634e-4c39-892a-50658abee05f',1790785069546,'ingest','AI_RAW','{"batch":0,"preview":"{\n  \"pages\": [\n    {\n      \"title\": \"家常红烧肉\",\n      \"category_slug\": \"caipu\",\n      \"action\": \"create\",\n      \"summary\": \"肥而不腻、红亮软糯的经典红烧肉做法\",\n      \"content\": \"## 难度与耗时\\n- **难度**：中等\\n- **耗时**：约80分钟\\n\\n## 食材\\n- 带皮[[五花肉]] 750g\\n- [[生姜]] 6片\\n- [[大葱]]段\\n- [[冰糖]] 15g\\n- [[八角]] 1个\\n- [[桂皮]] 小段\\n- [[香叶]] 2片\\n- [[生抽]] 2勺\\n- [[老抽]] 半勺\\n- [[料酒]] 2勺\\n- [[盐]] 少许\\n\\n## 步骤\\n1. [[五花肉]]切3厘米方块，冷水下锅，放姜片+1勺[[料酒]]，大火煮开，撇掉浮沫，继续煮3分钟捞出，温水冲洗干净。\\n2. 锅里放一点点油，小火下[[冰糖]]炒糖色：慢慢熬到冰糖融化变成枣红色，冒细密小泡，立刻倒入五花肉快速翻炒，肉块均匀裹上糖色。\\n3. 放葱姜、["}');
