INSERT INTO "wiki_debug_log" ("id","ts","tag","msg","data") VALUES('fd9dd839-c54f-4302-8af5-9e79056a0d2f',1790786624812,'ingest','AI_RAW','{"batch":0,"preview":"{\n  \"pages\": [\n    {\n      \"title\": \"刘姥姥\",\n      \"category_slug\": \"renwu\",\n      \"action\": \"create\",\n      \"summary\": \"乡下贫苦老太太，二进荣国府逛大观园，质朴幽默、不卑不亢。\",\n      \"content\": \"## 基本信息\\n- **身份**：乡下贫苦老太太，女婿家与贾府沾一点远亲\\n- **与我关系**：无直接关系（《红楼梦》人物）\\n- **别名**：母蝗虫（[[怡红院]]误闯后被戏称）\\n\\n## 性格与特征\\n质朴、幽默、通透、不卑不亢。心里明白大家是拿她打趣取乐，却愿意配合哄[[贾母]]开心。说话全是乡下土话，如“大火烧了毛毛虫”“花儿落了结个大倭瓜”。\\n\\n## 关键事件\\n- 第一年家里快饿死，带外孙板儿上门求助，[[王熙凤]]接济二十两银子渡过难关。\\n- 第二年秋收，挑着自家瓜果蔬菜专程来[[贾府]]道谢，即[[刘姥姥进大观园]]。\\n- 在[[秋爽斋]]宴席上说“老刘，老刘，食量大如牛；吃个老母猪，不抬头”，引爆全场大笑。\\n- 在[[栊"}');
