INSERT INTO "wiki_debug_log" ("id","ts","tag","msg","data") VALUES('d1b31bc3-80f2-4f39-ac1b-36baf9f5c270',1791720868346,'ingest','AI_RAW','{"batch":0,"preview":"{\n  \"pages\": [\n    {\n      \"title\": \"MyDiary前端重构项目\",\n      \"category_slug\": \"project\",\n      \"action\": \"create\",\n      \"summary\": \"MyDiary V2.2前端架构重构与体验升级迭代项目复盘\",\n      \"content\": \"## 项目概述\\n\\nMyDiary V2.2 前端架构重构与体验升级迭代项目，核心目标是对原有老旧页面架构进行解耦，统一弹窗组件、表单组件、路由权限体系，解决历史代码冗余、样式不统一、复用率低等长期遗留问题。\\n\\n- **项目周期**：三周\\n- **涉及模块**：前端重构、组件标准化、交互规范统一、兼容性回归测试\\n\\n## 技术决策\\n\\n### 组件库统一重构方案\\n\\n放弃局部修补优化方案，采用组件库统一重构方案：\\n\\n- 将项目全部弹窗、模态框统一接入自定义 Modal 规范体系\\n- 遵循统一入参、回调、显隐逻辑\\n- 彻底消灭碎片化写法\\n\\n### 路由集中式配置方案\\n\\n针对路由混乱问题，采用路由集中式配"}');
