INSERT INTO "wiki_debug_log" ("id","ts","tag","msg","data") VALUES('aa2e9e2d-cac1-48e5-a00a-f92caf1a3ea0',1791812383714,'ingest','AI_RAW','{"batch":0,"preview":"{\n  \"pages\": [\n    {\n      \"title\": \"2025年10月AI三线并进\",\n      \"category_slug\": \"📡_技术趋势\",\n      \"action\": \"create\",\n      \"summary\": \"2025年10月多模态、智能体、长上下文三条主线同时加速\",\n      \"content\": \"## 主题概述\\n2025年10月，AI 领域三条主线同时加速：\\n\\n1. **多模态生成能力全面升级**：视频生成从「能出片」走向「主体一致、细节可控」。\\n2. **智能体（Agent）从玩具变工具**：浏览器操作、文件管理、API 调用被整合进自然语言驱动的自动化流程。\\n3. **长上下文效率突破**：[[稀疏注意力机制]]大幅降低推理成本，使百万 token 级文档处理进入实用阶段。\\n\\n## 关联人物\\n（资料未提及具体人物）\\n\\n## 关联事件\\n- [[DeepSeek 长文本实验模型]]发布，稀疏注意力 + API 价格大幅下调\\n- 开源智能体平台对标 Manus，集成浏览器、文件系统与外部 API\\n-"}');
