INSERT INTO "chat_sessions" ("id","user_id","title","source_type","kb_id","msgs","created_at","updated_at") VALUES('sxyx7ufumv3q5i7p','08717303-45fb-4161-8b84-c2540337cdcb','你是？','wiki',NULL,'[{"role":"user","content":"你是？"},{"role":"ai","source_type":"wiki","content":"{\"action\":\"idle\",\"replyText\":\"你好呀，我是小麦～我专门帮你创建知识库。如果你想创建一个，可以告诉我它的名字，以及主要用来干嘛、包含哪些内容，我来帮你搞定！\"}"},{"role":"user","content":"我是信息化建设项目的负责人，我想建知识库"},{"role":"ai","source_type":"wiki","content":"{\n\"action\": \"chat\",\n\"replyText\": \"好嘞！那麻烦你告诉我一下，你打算给知识库起个什么名字？另外，主要想往里放哪些内容，比如项目文档、代码还是其他资料？\"\n}"},{"role":"user","content":"你帮我定"},{"role":"ai","source_type":"wiki","content":"{\n\"action\": \"chat\",\n\"replyText\": \"没问题，那我根据刚才了解的情况，给你拟定一个知识库名称：**【信息化建设项目知识资产库】**。它的说明是：专门用于存储和检索信息化建设过程中的项目文档、技术配置、会议纪要及经验分享，助力团队高效协作与知识沉淀。你觉得这个名字可以吗？或者你想做个微调？\"\n}"},{"role":"user","content":"可以"},{"role":"ai","source_type":"wiki","content":"好的，那就定名为【信息化建设项目知识资产库】，主要用来存放项目文档、技术配置、会议纪要等内容，帮助团队沉淀知识。确认无误的话，我这就去创建啦！\n\n📝 说明：专门用于存储和检索信息化建设过程中的项目文档、技术配置、会议纪要及经验分享，助力团队高效协作与知识沉淀。"},{"role":"ai","source_type":"wiki","content":"🎉 搞定！已为你创建「**信息化建设项目知识资产库**」知识库\n\n\n\n✅ 知识库已就绪，可以汇入资料了！\n\n💡 去「我的 → 知识库」看详情，或者选这个知识库开始提问～"}]',1791717187957,1794206430546);
INSERT INTO "chat_sessions" ("id","user_id","title","source_type","kb_id","msgs","created_at","updated_at") VALUES('ok4d3t3bmv3rl0x2','08717303-45fb-4161-8b84-c2540337cdcb','新对话','wiki',NULL,'[{"role":"ai","source_type":"wiki","content":"好呀！📚\n\n告诉我你想建个什么样的知识库：\n• **名字**叫什么？（比如：我的路亚笔记）\n• 主要**用来记录什么**？（比如：钓法技巧、装备评测、钓点分享）\n\n直接一句话说就行，比如：「路亚笔记，记录钓鱼经验和装备评测」"}]',1791719591654,1794206430546);
