PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id           TEXT PRIMARY KEY,                    -- uuid
  email        TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,                      -- pbkdf2 哈希
  nickname     TEXT DEFAULT '',
  avatar       TEXT DEFAULT '',
  created_at   INTEGER NOT NULL,                    -- unix timestamp
  updated_at   INTEGER NOT NULL
, last_login_at INTEGER DEFAULT 0, identity TEXT DEFAULT '', interests TEXT DEFAULT '', onboarding_done INTEGER DEFAULT 0);
CREATE TABLE profiles (
  user_id      TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  bio          TEXT DEFAULT '',
  theme        TEXT DEFAULT 'paper',                -- 主题
  default_mood TEXT DEFAULT 'calm',
  daily_goal   INTEGER DEFAULT 1,                   -- 每日目标篇数
  streak_start INTEGER,                             -- 连续写作开始日期
  streak_days  INTEGER DEFAULT 0,
  total_diaries INTEGER DEFAULT 0,
  total_words   INTEGER DEFAULT 0,
  updated_at   INTEGER NOT NULL
, remind_enabled INTEGER DEFAULT 0, remind_time TEXT DEFAULT '21:00', font TEXT DEFAULT 'hand');
CREATE TABLE feedbacks (
  id          TEXT PRIMARY KEY,                     -- uuid
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type        TEXT DEFAULT 'suggestion',           -- suggestion / bug / other
  title       TEXT DEFAULT '',
  content     TEXT NOT NULL,
  app_version TEXT DEFAULT '0.1.0',
  device      TEXT DEFAULT '',                      -- iPhone / Windows Chrome 等
  created_at  INTEGER NOT NULL
);
CREATE TABLE templates (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  icon TEXT DEFAULT '📋',
  description TEXT DEFAULT '',
  blocks TEXT NOT NULL,              -- JSON: DiaryBlock[]（模板的初始 blocks）
  default_title TEXT DEFAULT '',
  default_tags TEXT DEFAULT '[]',    -- JSON: string[]
  wallpaper TEXT DEFAULT '',
  show_lines INTEGER DEFAULT 1,      -- 0 or 1
  default_mood_id TEXT DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
, keywords TEXT DEFAULT '', is_public INTEGER DEFAULT 0, author_name TEXT DEFAULT '');
CREATE TABLE papers (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  description TEXT DEFAULT '',
  image_data TEXT NOT NULL,
  thumbnail TEXT DEFAULT '',
  show_lines INTEGER DEFAULT 1,
  is_public INTEGER DEFAULT 0,
  author_name TEXT DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE milestones (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,

  -- 类型: fixed | start | countdown
  type         TEXT NOT NULL,

  -- fixed 用这俩（存月日）
  target_mm    INTEGER,
  target_dd    INTEGER,

  -- start 用这个（起始日期 YYYY-MM-DD）
  start_date   TEXT,

  -- countdown 用这个（目标日期 YYYY-MM-DD）
  target_date  TEXT,

  -- 显示
  icon         TEXT DEFAULT '🎯',
  title        TEXT NOT NULL,
  description  TEXT DEFAULT '',
  diary_id     TEXT,                           -- 关联的日记 ID（可选）
  auto_created INTEGER DEFAULT 0,              -- 1 = AI 自动识别创建

  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL
);
CREATE TABLE plans (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,

  -- 目标日期（YYYY-MM-DD）— 可空（如果计划还没定日期）
  target_date  TEXT,

  -- 状态: pending(待办) | completed(已完成) | overdue(已过期)
  status       TEXT NOT NULL DEFAULT 'pending',

  -- 显示
  icon         TEXT DEFAULT '🎯',
  title        TEXT NOT NULL,
  description  TEXT DEFAULT '',
  diary_id     TEXT,
  auto_created INTEGER DEFAULT 0,

  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL
);
CREATE TABLE daily_summaries (
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  date         TEXT NOT NULL,              -- YYYY-MM-DD
  summary      TEXT NOT NULL,              -- AI 生成的一句话总结
  diary_count  INTEGER DEFAULT 0,          -- 当天有几篇日记（生成时计数）
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL,
  PRIMARY KEY (user_id, date)
);
CREATE TABLE diary_embeddings (
  diary_id  TEXT PRIMARY KEY,
  user_id   TEXT NOT NULL,
  content   TEXT NOT NULL,
  vector    TEXT NOT NULL,       -- JSON 数组，如 "[0.123, -0.456, ...]"
  FOREIGN KEY (diary_id) REFERENCES diaries(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE wiki_knowledge_bases (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL,
  title      TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
, slug TEXT, is_official INTEGER DEFAULT 0, description TEXT DEFAULT '');
CREATE TABLE wiki_categories (
  id            TEXT PRIMARY KEY,
  kb_id         TEXT NOT NULL,
  user_id       TEXT NOT NULL,
  name          TEXT NOT NULL,
  slug          TEXT NOT NULL,
  sort_order    INTEGER NOT NULL DEFAULT 0,
  extract_hints TEXT NOT NULL DEFAULT '',
  page_format   TEXT NOT NULL DEFAULT '',
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL,
  UNIQUE(kb_id, slug)
);
CREATE TABLE wiki_pages (
  id          TEXT PRIMARY KEY,
  kb_id       TEXT NOT NULL,
  user_id     TEXT NOT NULL,
  category_id TEXT,
  title       TEXT NOT NULL,
  content     TEXT NOT NULL,
  vector      TEXT,
  source_ids  TEXT,
  is_system   INTEGER NOT NULL DEFAULT 0,
  created_at  INTEGER NOT NULL,
  updated_at  INTEGER NOT NULL, summary TEXT,
  UNIQUE(kb_id, title)
);
CREATE TABLE wiki_links (
  id          TEXT PRIMARY KEY,
  kb_id       TEXT NOT NULL,
  user_id     TEXT NOT NULL,
  from_title  TEXT NOT NULL,
  to_title    TEXT NOT NULL,
  relation    TEXT DEFAULT 'related',
  created_at  INTEGER NOT NULL
);
CREATE TABLE wiki_templates (
  id            TEXT PRIMARY KEY,
  kb_id         TEXT,                       -- NULL = 官方预设（所有 KB 可见）
  user_id       TEXT,                       -- 'system' = 官方预设
  name          TEXT NOT NULL,
  description   TEXT,
  extract_hints TEXT NOT NULL DEFAULT '',
  page_format   TEXT NOT NULL DEFAULT '',
  kind          TEXT NOT NULL DEFAULT 'user',  -- official | user
  builtin_key   TEXT,                       -- 官方预设的唯一标识（用于 upsert）
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
, category TEXT DEFAULT '通用');
CREATE TABLE activity_logs (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  action TEXT NOT NULL,
  detail TEXT,
  created_at INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS "wiki_sources" (id TEXT PRIMARY KEY, kb_id TEXT, user_id TEXT NOT NULL, kind TEXT NOT NULL, ref_id TEXT, title TEXT, raw_text TEXT NOT NULL, ingested INTEGER NOT NULL DEFAULT 0, ingested_at INTEGER, created_at INTEGER NOT NULL, tags TEXT, source TEXT DEFAULT 'paste');
CREATE TABLE IF NOT EXISTS "diaries" (
  id                 TEXT PRIMARY KEY,
  user_id            TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  date               TEXT NOT NULL,
  template_id        TEXT DEFAULT 'diary',
  title              TEXT DEFAULT '',
  mood_id            TEXT DEFAULT 'calm',
  tags               TEXT DEFAULT '[]',
  weather            TEXT,
  blocks             TEXT DEFAULT '[]',
  created_at         INTEGER NOT NULL,
  updated_at         INTEGER NOT NULL,
  deleted_at         INTEGER,
  capsule_unlock_at  INTEGER,
  wallpaper          TEXT,
  show_lines         INTEGER DEFAULT 1
);
CREATE TABLE wiki_debug_log (id TEXT PRIMARY KEY, ts INTEGER NOT NULL, tag TEXT, msg TEXT, data TEXT);
CREATE TABLE chat_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT DEFAULT '新对话', source_type TEXT NOT NULL DEFAULT 'diary', kb_id TEXT, msgs TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_feedbacks_user ON feedbacks(user_id);
CREATE INDEX idx_feedbacks_created ON feedbacks(created_at);
CREATE INDEX idx_templates_user ON templates(user_id);
CREATE INDEX idx_papers_user ON papers(user_id);
CREATE INDEX idx_papers_public ON papers(is_public);
CREATE INDEX idx_milestones_user ON milestones(user_id);
CREATE INDEX idx_plans_user ON plans(user_id);
CREATE INDEX idx_ds_user ON daily_summaries(user_id);
CREATE INDEX idx_embeddings_user ON diary_embeddings(user_id);
CREATE INDEX idx_wiki_kb_user ON wiki_knowledge_bases(user_id);
CREATE INDEX idx_wiki_cat_kb ON wiki_categories(kb_id);
CREATE INDEX idx_wiki_pages_kb ON wiki_pages(kb_id);
CREATE INDEX idx_wiki_links_kb ON wiki_links(kb_id, from_title);
CREATE INDEX idx_wiki_tpl_kb ON wiki_templates(kb_id);
CREATE INDEX idx_activity_logs_user ON activity_logs(user_id);
CREATE INDEX idx_activity_logs_action ON activity_logs(action);
CREATE INDEX idx_activity_logs_time ON activity_logs(created_at);
CREATE UNIQUE INDEX uq_wiki_links ON wiki_links(kb_id, user_id, from_title, to_title, COALESCE(relation,''));
CREATE INDEX idx_chat_sessions_user ON chat_sessions(user_id);
CREATE INDEX idx_chat_sessions_kb ON chat_sessions(kb_id);
CREATE TRIGGER bump_kb_update_after_page_insert AFTER INSERT ON wiki_pages BEGIN UPDATE wiki_knowledge_bases SET updated_at = strftime('%s','now') WHERE id = NEW.kb_id; END;
CREATE TRIGGER bump_kb_update_after_page_update AFTER UPDATE ON wiki_pages BEGIN UPDATE wiki_knowledge_bases SET updated_at = strftime('%s','now') WHERE id = NEW.kb_id; END;
CREATE TRIGGER bump_kb_update_after_page_delete AFTER DELETE ON wiki_pages BEGIN UPDATE wiki_knowledge_bases SET updated_at = strftime('%s','now') WHERE id = OLD.kb_id; END;
